pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(newOwner != address(0));
        address oldOwner = c.owner();
        vm.assume(caller != address(0));
        // drive c through setOwner
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        // General rule: success iff caller was the current owner;
        // success => owner == newOwner, failure => owner != newOwner (owner unchanged, newOwner != old owner enforced below)
        vm.assume(newOwner != oldOwner);
        assertTrue(ok ? c.owner() == newOwner : c.owner() != newOwner);
    }
}

